<label>SMTP host<input name="host" value="{{ old('host',$smtp['host']??'') }}" required maxlength="253" placeholder="smtp.example.com"></label><div class="field-grid"><label>Port<input name="port" type="number" min="1" max="65535" value="{{ old('port',$smtp['port']??587) }}" required></label><label>Encryption<select name="encryption"><option value="tls" @selected(($smtp['encryption']??'tls')==='tls')>TLS / STARTTLS</option><option value="ssl" @selected(($smtp['encryption']??'')==='ssl')>SSL / implicit TLS</option></select></label></div><label>Username<input name="username" value="{{ old('username',$smtp['username']??'') }}" maxlength="255" autocomplete="off"></label><label>SMTP password<input name="password" type="password" autocomplete="new-password" maxlength="1024" placeholder="{{ empty($smtp)?'SMTP password':'Leave blank to keep current password' }}"></label><label>Sender email<input name="from_address" type="email" value="{{ old('from_address',$smtp['from_address']??'') }}" required></label><label>Sender name<input name="from_name" value="{{ old('from_name',$smtp['from_name']??'SecureVault') }}" required maxlength="100"></label>
